from pathlib import Path
import subprocess, tempfile
s=(Path(__file__).resolve().parents[1]/'Selene/ViewControllers/TVStreamExperience.swift').read_text()
body=s.split('@objcMembers final class TVClientPreferences: NSObject {')[1].split('\nclass TVDarkTableController')[0]
program='import Foundation\nfinal class TVClientPreferences: NSObject {'+body+'\nlet defaults = UserDefaults.standard\nlet ids = ["altTab", "windows", "esc", "enter", "text", "capabilities"]\nfor id in ids { defaults.removeObject(forKey:"Selene.tv.shortcut." + id); assert(TVClientPreferences.shortcutVisible(id)); TVClientPreferences.setShortcutVisible(id,visible:false);assert(!TVClientPreferences.shortcutVisible(id)); defaults.removeObject(forKey:"Selene.tv.shortcut." + id) }\ndefaults.removeObject(forKey:"Selene.tv.compactCovers")\nassert(!TVClientPreferences.compactCovers)\nTVClientPreferences.compactCovers=true\nassert(defaults.bool(forKey:"Selene.tv.compactCovers"))\ndefaults.removeObject(forKey:"Selene.tv.compactCovers")\ndefaults.removeObject(forKey:"Selene.tv.lockOnDisconnect")\nassert(!TVClientPreferences.lockOnDisconnect)\nTVClientPreferences.lockOnDisconnect=true\nassert(defaults.bool(forKey:"Selene.tv.lockOnDisconnect"))\ndefaults.removeObject(forKey:"Selene.tv.lockOnDisconnect")\nfor side in ["left","right"] { defaults.removeObject(forKey:"Selene.tv." + side + "Deadzone"); assert(TVClientPreferences.deadzone(side)==0); TVClientPreferences.setDeadzone(side,value:31);assert(TVClientPreferences.deadzone(side)==30); TVClientPreferences.setDeadzone(side,value:-1);assert(TVClientPreferences.deadzone(side)==0); defaults.removeObject(forKey:"Selene.tv." + side + "Deadzone") }\ndefaults.removeObject(forKey:"Selene.tv.askReconnectOnReturn")\nassert(!TVClientPreferences.askReconnectOnReturn)\nTVClientPreferences.askReconnectOnReturn=true\nassert(defaults.bool(forKey:"Selene.tv.askReconnectOnReturn"))\ndefaults.removeObject(forKey:"Selene.tv.askReconnectOnReturn")\nprint("PASS: cover/shortcut/lock/reconnect defaults, preference persistence and deadzone bounds")\n'
with tempfile.TemporaryDirectory() as directory:
 p=Path(directory)/'preferences.swift';p.write_text(program)
 subprocess.run(['/Applications/Xcode.app/Contents/Developer/Toolchains/XcodeDefault.xctoolchain/usr/bin/swift',str(p)],check=True)
